SQL = (
    "-- File generated by Dolibarr 24.0.1 --;\n"
    "INSERT INTO llx_website_page(rowid, pageurl, aliasalt, lang, status,"
    " type_container, title, content, image) VALUES("
    "1__+MAX_llx_website_page__, 'home', ',accueil,', '', '1', 'page',"
    " 'Home', '<img src=\"/medias/image/__WEBSITE_KEY__/logo.png\">"
    " __[MAIN_INFO_SOCIETE_NOM]__', '');\n"
    "INSERT INTO llx_website_page(rowid, pageurl, aliasalt, lang, status,"
    " type_container, title, content, image) VALUES("
    "2__+MAX_llx_website_page__, 'bad page!', '', 'english', '0', 'page',"
    " 'Bad', 'x', '');\n"
    "UPDATE llx_website SET fk_default_home = 1__+MAX_llx_website_page__"
    " WHERE rowid = __WEBSITE_ID__;\n"
    "UPDATE llx_website SET lang = '' WHERE rowid = __WEBSITE_ID__;\n"
)


def make_zip(files, infos=()):
    """Zip in memory; files maps name to bytes or str, infos adds ZipInfo."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for name, data in files.items():
            zf.writestr(name, data)
        for info, data in infos:
            zf.writestr(info, data)
    return buf.getvalue()


def with_encrypted_flag(data):
    """Set the encryption bit of the first central directory header.

    zipfile.writestr() resets flag_bits, so the bit is set in the bytes.
    """
    pos = data.find(b"PK\x01\x02")
    (flags,) = struct.unpack_from("<H", data, pos + 8)
    return data[: pos + 8] + struct.pack("<H", flags | 0x1) + data[pos + 10 :]


def with_eocd_count(data, count):
    """Patch the entry counts of the end of central directory record."""
    pos = data.rfind(b"PK\x05\x06")
    return (
        data[: pos + 8] + struct.pack("<HH", count, count) + data[pos + 12 :]
    )


def with_zip64_record(data, cd_size):
    """Insert a zip64 end record and locator before a normal EOCD."""
    pos = data.rfind(b"PK\x05\x06")
    record = b"PK\x06\x06" + struct.pack(
        "<QHHIIQQQQ", 44, 45, 45, 0, 0, 1, 1, cd_size, 0
    )
    locator = b"PK\x06\x07" + struct.pack("<IQI", 0, pos, 1)
    return data[:pos] + record + locator + data[pos:]


def stored_zip(name, payload):
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_STORED) as zf:
        zf.writestr(name, payload)
    return buf.getvalue()


def demo_files():
    return {
        "website_pages.sql": SQL,
        "containers/htmlheader.html": "<link rel='stylesheet' href='x.css'>",
        "containers/styles.css.php": "body{}",
        "containers/index.php": "<?php echo 1;",
        "README.md": "Demo  site\ncredits text",
        "medias/image/websitekey/logo.png": b"\x89PNG",
        "medias/image/websitekey/bad').png": b"\x89PNG",
        "medias/js/websitekey/app.js": "var a;",
    }


class ZipsourceCases:
    def test_key_from_filename(self):
        self.assertEqual(
            key_from_filename("website_exemplesite-20260101120000-V24.zip"),
            "exemplesite",
        )
        self.assertEqual(
            key_from_filename("/tmp/website_template-corporate.zip"),
            "template-corporate",
        )
        self.assertEqual(key_from_filename("export.zip"), "")

    def test_load_zip(self):
        data = make_zip(demo_files())
        site = load_zip(data, Options(filename="website_exemplesite.zip"))
        self.assertEqual(site.source_key, "exemplesite")
        self.assertEqual(site.dolibarr_version, "24.0.1")
        self.assertEqual(site.home_ref, "home")
        self.assertEqual(site.main_lang, "en")
        codes = [f.code for f in site.findings]
        self.assertIn("main_lang_defaulted", codes)
        self.assertIn("credits", codes)
        self.assertIn("media_name_refused", codes)
        self.assertNotIn("ref_slugified", codes, "only kept rows")
        home = site.page("home")
        self.assertEqual(home.aliases, ["accueil"])
        self.assertIn("/medias/image/exemplesite/logo.png", home.body_html)
        self.assertTrue(home.published)
        self.assertIsNone(site.page("bad page!"))
        bad = site.page("bad-page")
        self.assertIsNone(bad, "invalid language skips the page")
        self.assertIn("page_error", codes)
        self.assertEqual(
            sorted(m.relpath for m in site.media),
            ["image/exemplesite/logo.png", "js/exemplesite/app.js"],
        )
        self.assertEqual(site.site_css, "body{}")
        credits = [f for f in site.findings if f.code == "credits"][0]
        self.assertEqual(credits.params["text"], "Demo site credits text")

    def test_read_media_bytes(self):
        data = make_zip(demo_files())
        opts = Options(filename="website_exemplesite.zip")
        source = zipsource.open_zip(data, opts)
        site = load_zip(data, opts, source=source)
        logo = [m for m in site.media if m.relpath.endswith("logo.png")][0]
        self.assertEqual(source.read_media(logo), b"\x89PNG")

    def test_oversized_media_is_skipped(self):
        files = demo_files()
        files["medias/image/websitekey/big.png"] = b"B" * 10
        data = make_zip(files)
        site = load_zip(
            data,
            Options(
                filename="website_exemplesite.zip", zip_limits={"max_media": 5}
            ),
        )
        rels = [m.relpath for m in site.media]
        self.assertNotIn("image/exemplesite/big.png", rels)
        self.assertNotIn("js/exemplesite/app.js", rels)
        self.assertEqual(rels, ["image/exemplesite/logo.png"])
        big = [f for f in site.findings if f.code == "media_too_large"]
        self.assertEqual(
            sorted(f.params["relpath"] for f in big),
            ["image/exemplesite/big.png", "js/exemplesite/app.js"],
        )

    def test_invalid_key_is_source_error(self):
        data = make_zip(demo_files())
        with self.assertRaises(SourceError):
            load_zip(data, Options(filename="website_a{{1+1}}.zip"))

    def test_missing_sql_is_source_error(self):
        with self.assertRaises(SourceError):
            load_zip(make_zip({"README.md": "x"}), Options(source_key="k"))

    def test_entry_count_checked_before_zipfile(self):
        data = make_zip({"f%d" % i: "x" for i in range(4)})
        with mock.patch.object(
            zipsource.zipfile, "ZipFile", side_effect=AssertionError
        ) as zf:
            with self.assertRaises(SourceError):
                ZipSource(data, ZipLimits(max_entries=3))
            zf.assert_not_called()

    def test_lying_eocd_count_is_caught_before_zipfile(self):
        data = with_eocd_count(make_zip({"f%d" % i: "x" for i in range(6)}), 1)
        with mock.patch.object(
            zipsource.zipfile, "ZipFile", side_effect=AssertionError
        ) as zf:
            with self.assertRaises(SourceError):
                ZipSource(data, ZipLimits(max_entries=3))
            zf.assert_not_called()

    def test_zip64_locator_is_honoured_without_sentinels(self):
        data = with_zip64_record(make_zip({"a": "x"}), 1 << 40)
        with mock.patch.object(
            zipsource.zipfile, "ZipFile", side_effect=AssertionError
        ) as zf:
            with self.assertRaises(SourceError):
                ZipSource(data)
            zf.assert_not_called()

    def test_zip64_decoy_locator_offset_is_refused(self):
        base = make_zip({"f%d" % i: "x" for i in range(6)})
        pos = base.rfind(b"PK\x05\x06")
        (cd_size,) = struct.unpack_from("<I", base, pos + 12)
        decoy = b"PK\x06\x06" + struct.pack(
            "<QHHIIQQQQ", 44, 45, 45, 0, 0, 1, 1, 0, 0
        )
        real = b"PK\x06\x06" + struct.pack(
            "<QHHIIQQQQ", 44, 45, 45, 0, 0, 6, 6, cd_size, 0
        )
        locator = b"PK\x06\x07" + struct.pack("<IQI", 0, 0, 1)
        data = decoy + base[:pos] + real + locator + base[pos:]
        with mock.patch.object(
            zipsource.zipfile, "ZipFile", side_effect=AssertionError
        ) as zf:
            with self.assertRaises(SourceError):
                ZipSource(data, ZipLimits(max_entries=3))
            zf.assert_not_called()

    def test_directory_bounds_are_checked(self):
        big = with_zip64_record(make_zip({"a": "x"}), 10**6)
        with self.assertRaises(SourceError):
            ZipSource(big, ZipLimits(max_central_directory=10**9))
        data = make_zip({"a": "x", "b": "y"})
        pos = data.find(b"PK\x01\x02")
        broken = data[:pos] + b"PK\x09\x09" + data[pos + 4 :]
        with mock.patch.object(
            zipsource.zipfile, "ZipFile", side_effect=AssertionError
        ) as zf:
            with self.assertRaises(SourceError):
                ZipSource(broken)
            zf.assert_not_called()

    def test_truncated_zip64_record_is_source_error(self):
        data = with_zip64_record(make_zip({"a": "x"}), 10)
        pos = data.rfind(b"PK\x06\x06")
        loc = data.rfind(b"PK\x06\x07")
        data = data[: pos + 12] + data[loc:]
        with self.assertRaises(SourceError):
            ZipSource(data)

    def test_read_failures_are_source_errors(self):
        data = stored_zip("medias/image/websitekey/a.png", b"hello world")
        lying = data.replace(b"hello world", b"hellO world")
        source = ZipSource(lying)
        with self.assertRaises(SourceError):
            source.read("medias/image/websitekey/a.png", 100)
        pos = data.find(b"PK\x01\x02")
        odd = data[: pos + 10] + struct.pack("<H", 99) + data[pos + 12 :]
        source = ZipSource(odd)
        with self.assertRaises(SourceError):
            source.read("medias/image/websitekey/a.png", 100)

    def test_duplicate_media_keeps_the_key_folder(self):
        files = demo_files()
        files["medias/image/exemplesite/logo.png"] = b"KEY!"
        data = make_zip(files)
        opts = Options(filename="website_exemplesite.zip")
        source = zipsource.open_zip(data, opts)
        site = load_zip(data, opts, source=source)
        logos = [m for m in site.media if m.relpath.endswith("logo.png")]
        self.assertEqual(len(logos), 1)
        self.assertEqual(source.read_media(logos[0]), b"KEY!")
        dup = [f for f in site.findings if f.code == "media_duplicate"]
        self.assertEqual(
            [f.params["relpath"] for f in dup], ["image/exemplesite/logo.png"]
        )

    def test_refused_entries(self):
        link = zipfile.ZipInfo("medias/image/websitekey/l.png")
        link.external_attr = (stat.S_IFLNK | 0o777) << 16
        for bad in (
            make_zip({}, [(link, b"/etc/passwd")]),
            with_encrypted_flag(make_zip({"website_pages.sql": "x"})),
            make_zip({"../x.sql": "x"}),
            make_zip({"/abs.sql": "x"}),
            make_zip({"a.txt": "x"}, [(zipfile.ZipInfo("a.txt"), b"y")]),
            make_zip({"zeros.bin": b"\x00" * 300000}),
        ):
            with self.assertRaises(SourceError):
                ZipSource(bad)

    def test_total_and_read_limits(self):
        data = make_zip({"a": "x" * 50, "b": "y" * 50})
        with self.assertRaises(SourceError):
            ZipSource(data, ZipLimits(max_total=60, max_ratio=10**6))
        source = ZipSource(data, ZipLimits(max_ratio=10**6))
        with self.assertRaises(SourceError):
            source.read("a", 10)
        self.assertEqual(source.read("a", 100), b"x" * 50)

    def test_not_a_zip(self):
        with self.assertRaises(SourceError):
            ZipSource(b"not a zip at all")

    def test_decode_text_and_placeholders(self):
        latin = ("Société générale, café, élève, " * 20).encode("latin-1")
        self.assertIn("café", decode_text(latin))
        self.assertEqual(decode_text(b"\xef\xbb\xbfabc"), "abc")
        self.assertEqual(
            find_placeholders("a __(Key)__ b __[CONST]__ __12__ __N__"),
            ["__(Key)__", "__[CONST]__", "__12__"],
        )


class TestZipsource(ZipsourceCases, unittest.TestCase):
    pass
